def _coerce(value: str, target_type: type) -> Any:
    """Convert a string to the target type, raising EnvCfgError on failure."""
    if target_type is int:
        try:
            return int(value)
        except ValueError:
            raise EnvCfgError(f"{value!r} cannot be coerced to int")
    if target_type is float:
        try:
            return float(value)
        except ValueError:
            raise EnvCfgError(f"{value!r} cannot be coerced to float")
    if target_type is bool:
        lower = value.lower()
        if lower in ("true", "1", "yes"):
            return True
        if lower in ("false", "0", "no"):
            return False
        raise EnvCfgError(f"{value!r} cannot be coerced to bool")
    if target_type is str:
        return value
    raise EnvCfgError(f"Unsupported target type {target_type!r}")


