import os
import tempfile
from pathlib import Path

import pytest

from envcfg import EnvCfgError, load


def _env(prefix: str, **kwargs: str) -> dict[str, str]:
    return {f"{prefix}__{k.upper()}": v for k, v in kwargs.items()}


def _defaults(prefix: str, **kwargs: Any) -> dict:
    return {f"{prefix}__{k.upper()}": v for k, v in kwargs.items()}


def _toml(prefix: str, **kwargs: Any) -> dict:
    return {f"{prefix}__{k.upper()}": v for k, v in kwargs.items()}


def test_defaults_only():
    cfg = load(_defaults("APP", port=80, debug=True))
    assert cfg == {"APP__PORT": 80, "APP__DEBUG": True}


def test_defaults_overridden_by_toml():
    cfg = load(
        _defaults("APP", port=80, debug=True),
        toml_path="test_envcfg.py",  # dummy, will be overwritten
    )
    assert cfg == {"APP__PORT": 80, "APP__DEBUG": True}


def test_defaults_overridden_by_env():
    cfg = load(
        _defaults("APP", port=80, debug=True),
        env=_env("APP", port="90", debug="false"),
    )
    assert cfg == {"APP__PORT": 90, "APP__DEBUG": False}


def test_nested_defaults():
    cfg = load(
        _defaults("APP", server={"port": 80, "host": "localhost"}),
    )
    assert cfg == {
        "APP__SERVER__PORT": 80,
        "APP__SERVER__HOST": "localhost",
    }


def test_nested_defaults_overridden_by_toml():
